import{_ as t}from"./chunks/NPU侧运行验证步骤.BFaRF1G3.js";import{c as a,Q as s,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const r="/assets/asynchronous_execution.CSXyBX1P.png",i="/assets/asynchronous_execution_async.B1Klzq1V.png",v=JSON.parse('{"title":"异步执行","description":"","frontmatter":{},"headers":[{"level":1,"title":"异步执行","slug":"异步执行"},{"level":2,"title":"Stream管理","slug":"stream管理"},{"level":2,"title":"Memory（内存）管理","slug":"memory内存管理"},{"level":2,"title":"异步调用","slug":"异步调用"},{"level":2,"title":"同步等待","slug":"同步等待"},{"level":2,"title":"更多的Runtime高级特性","slug":"更多的runtime高级特性"}],"relativePath":"guide/编程指南/编译与运行/异步执行.md","filePath":"guide/编程指南/编译与运行/异步执行.md"}'),c={name:"guide/编程指南/编译与运行/异步执行.md"};function o(p,e,m,d,h,u){return s(),n("div",null,[...e[0]||(e[0]=[l(`<h1 id="异步执行" tabindex="-1">异步执行 <a class="header-anchor" href="#异步执行" aria-label="Permalink to &quot;异步执行&quot;">​</a></h1><p>当开发者完成一个Kernel核函数的编写后，需要通过特定的下发/启动语法将其提交到指定的Stream（计算流）上执行。例如：</p><div class="language-c++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c++</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     kernel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">numBlocks, ubufDynSize, stream</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(参数列表);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     // 或使用对应的API：aclrtLaunchKernel*(...)</span></span></code></pre></div><p>这些核Kernel核函数都是通过CANN Runtime完成Kernel的加载与运行。CANN Runtime是CANN软件栈中负责驱动硬件执行与管理AI计算任务的核心组件，它通过提供Device、Memory、Context、Stream、Kernel管理等API，使得上层应用和框架能够高效利用AI处理器的硬件计算资源。</p><p>完成Kernel加载和运行的主要流程分以下几步：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  1. 初始化：aclInit。</span></span>
<span class="line"><span>  2. 运行时资源申请：通过aclrtSetDevice和aclrtCreateStream分别申请Device、Stream运行管理资源。</span></span>
<span class="line"><span>  3. 如果需要Device内存参与计算，使用aclrtMalloc分配Device内存，通过aclrtMemcpy或aclrtMemcpyAsync将Host侧内存拷贝到Device侧。</span></span>
<span class="line"><span>  4. 通过kernel&lt;&lt;&lt;numBlocks, ubufDynSize, stream&gt;&gt;&gt;(参数列表) 调用核函数，完成核函数的异步执行。</span></span>
<span class="line"><span>  5. 执行核函数后，需要同步等待核函数的执行完成。</span></span>
<span class="line"><span>  6. 如果Host需要Device内存的计算结果，使用aclrtMemcpy或aclrtMemcpyAsync将Device侧内存拷贝到Host侧。</span></span>
<span class="line"><span>  7. 资源释放：通过aclrtDestroyStream和aclrtResetDevice分别释放Stream、Device运行管理资源。</span></span>
<span class="line"><span>  8. 去初始化：aclFinalize。</span></span></code></pre></div><p><img src="`+t+'" alt=""></p><p>在这个过程中我们提到了Stream创建与销毁，内存申请与拷贝，异步调用与同步等待。在本节的其余部分，我们将解释这些CANN Runtime的元素和对应的API。</p><h2 id="stream管理" tabindex="-1">Stream管理 <a class="header-anchor" href="#stream管理" aria-label="Permalink to &quot;Stream管理&quot;">​</a></h2><p>Stream（计算流）本质上是一个有序的任务队列，为开发者提供了一种表示“先序执行”的抽象机制，程序可向队列中提交各类操作，例如内存拷贝、核函数下发等，所有任务将按入队顺序依次执行。单个计算流内，队列头部任务优先执行，执行完成后自动出队；后续队列任务依次前移，等待调度执行。同一个计算流中的任务具备串行执行特性，严格遵循入队先后顺序运行。</p><p>应用程序可同时创建并使用多个计算流。多流场景下，运行时会根据AI 处理器的硬件资源占用状态，从存有待处理任务的计算流中择优调度任务执行。开发者可为计算流配置优先级，该优先级将作为运行时调度的参考依据，用以调整任务调度策略，但无法强制保证固定的执行顺序。</p><p>绑定在指定计算流内的API接口调用、核函数下发操作，相对于主机CPU线程均为异步执行。 应用程序可通过等待目标计算流清空所有任务完成流级同步，也可在整个设备维度完成全局同步。</p><p>CANN Runtime内置默认计算流，所有未显式指定计算流的运算操作、核函数下发任务，都会默认排入该流中执行。绝大多数未手动指定计算流的业务代码，都在隐式使用默认计算流。</p><ul><li><strong>创建与销毁Stream</strong>： <code>aclrtCreateStream(&amp;stream)</code>与<code>aclrtDestroyStream(stream)</code>。</li><li><strong>指定Stream执行核函数</strong>： <code>kernel&lt;&lt;&lt;numBlocks, 0, stream&gt;&gt;&gt;(...)</code>。</li><li><strong>指定Stream异步拷贝</strong>： <code>aclrtMemcpyAsync(..., stream)</code>。</li><li><strong>指定Stream同步</strong>：<code>aclrtSynchronizeStream(stream)</code>。</li></ul><h2 id="memory-内存-管理" tabindex="-1">Memory（内存）管理 <a class="header-anchor" href="#memory-内存-管理" aria-label="Permalink to &quot;Memory（内存）管理&quot;">​</a></h2><p>在异构计算架构中，系统由主机（Host）和设备（Device）组成。Host和Device各自拥有独立的内存，Host内存是指AI处理器所在服务器的主机内存（即CPU内存），而Device内存则是指AI处理器自带的设备内存。</p><p>内存管理中要做好的两件事是：</p><ol><li><strong>可以访问内存</strong>：Runtime提供了一套内存管理API，使开发者能够高效便捷地编写应用程序中的内存管理代码。由于Host和Device的内存相互独立，Runtime提供了专门的接口来分别申请和释放Host内存及Device内存。例如，申请和释放Host内存的接口为aclrtMallocHost和aclrtFreeHost，而申请和释放Device内存的接口为aclrtMalloc和aclrtFree。</li><li><strong>高效访问内存</strong>：算子在Device上执行过程中，访问Device上的Device内存数据性能更高。为此，Runtime提供了Host与Device之间互相拷贝内存的接口，支持同步和异步方式，例如aclrtMemcpy和aclrtMemcpyAsync等，以便开发者更好地规划数据的存储与访问。</li></ol><h2 id="异步调用" tabindex="-1">异步调用 <a class="header-anchor" href="#异步调用" aria-label="Permalink to &quot;异步调用&quot;">​</a></h2><p>为了能够更好的发挥CPU和AI处理器的硬件利用率，CANN Runtime遵循“下发即返回”的异步执行策略，使 Host 在提交 H2D/D2H 拷贝或 Kernel 计算任务后立即继续执行后续逻辑，从而让主机侧调度、设备侧计算、主机与设备之间的数据传输尽可能重叠执行，隐藏传输和调度开销，提高端到端吞吐率。</p><p>典型&lt;&lt;&lt;&gt;&gt;&gt;异步调用的场景是：将主机与设备计算操作重叠执行，从而提升主机侧与设备侧计算资源利用率。 <img src="'+r+'" alt=" " title="Kernel异步调用"></p><p>同样地，将aclrtMemcpy替换成aclrtMemcpyAsync接口，可以实现主机与设备的内存传输与计算操作重叠执行，从而降低甚至消除内存传输带来的性能开销。 <img src="'+i+'" alt=" " title="内存传输异步并发执行"></p><h2 id="同步等待" tabindex="-1">同步等待 <a class="header-anchor" href="#同步等待" aria-label="Permalink to &quot;同步等待&quot;">​</a></h2><p>核函数的调用是异步的，在核函数调用结束之后，控制权立刻返回给主机端，需要在host等待核函数的执行完成，可以通过以下接口强制Host程序等待核函数执行完毕：</p><table tabindex="0"><thead><tr><th>同步接口</th><th>接口描述</th></tr></thead><tbody><tr><td><code>aclrtSynchronizeDevice()</code></td><td>阻塞Host侧当前线程，直到与当前线程绑定的Context所对应的Device中的所有操作都已完成。</td></tr><tr><td><code>aclrtSynchronizeStream()</code></td><td>阻塞Host侧当前线程直到指定Stream中的所有操作都已完成。</td></tr></tbody></table><h2 id="更多的runtime高级特性" tabindex="-1">更多的Runtime高级特性 <a class="header-anchor" href="#更多的runtime高级特性" aria-label="Permalink to &quot;更多的Runtime高级特性&quot;">​</a></h2><p>更多的Runtime编程方式及接口，可以参考<a href="https://hiascend.com/document/redirect/CannCommunityadev" target="_blank" rel="noreferrer">《应用开发（C&amp;C++）》</a>。</p>',27)])])}const k=a(c,[["render",o]]);export{v as __pageData,k as default};
